SELECT dept_name, budget_bucket, stddev_budget FROM (SELECT dept_name, CASE WHEN budget >= 3371000 THEN 'high' WHEN budget >= 1694000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND(STDDEV(budget), 2) AS stddev_budget FROM departments WHERE budget < 2087000 GROUP BY dept_name, CASE WHEN budget >= 3371000 THEN 'high' WHEN budget >= 1694000 THEN 'mid' ELSE 'low' END) AS x WHERE stddev_budget < 73
